-- Two-paper editorial revision: new immutable versions only, preserve all attempts and historical banks.
begin;
insert into academy_tcf_reading.papers(id,version,content) values
('tcf-reading-01','tcf-reading-2026-11-editorial-v4',$paper${"id":"tcf-reading-01","version":"tcf-reading-2026-11-editorial-v4","title":"TCF Reading · Test 01","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Information à tous les voyageurs : En raison de fortes chutes de neige, tous les vols à destination de Genève sont annulés ce lundi. Les passagers concernés peuvent modifier leur billet sans frais. Aéroport International de Lyon","question":"Que doivent faire les passagers concernés par cette annonce ?","options":["Demander un nouveau trajet sans frais","Modifier la destination en payant un supplément","Se présenter pour un vol à l'heure prévue","Attendre une reprise des vols pour Genève"],"correct":"A","explanation":"« Les passagers concernés peuvent modifier leur billet sans frais » : le changement de vol est gratuit."},{"number":2,"points":3,"passage":"Message de la bibliothèque : Le retour des livres empruntés est prolongé jusqu’au 10 janvier, sans pénalité. Vous pouvez également utiliser la boîte extérieure prévue à cet effet. Bibliothèque municipale","question":"Que propose la bibliothèque à ses usagers ?","options":["Déposer uniquement les livres le 10 janvier","Rendre les emprunts sans pénalité avant le 10 janvier","Renouveler tous les prêts pour un mois","Retirer les livres à la bibliothèque après la date"],"correct":"B","explanation":"Le retour est prolongé « jusqu’au 10 janvier, sans pénalité ». Aucune prolongation sans limite n’est annoncée."},{"number":3,"points":3,"passage":"Cher(e)s client(e)s, Notre boutique en ligne sera en maintenance le jeudi 7 mars de 1 h à 5 h du matin. Pendant cette période, aucune commande ne pourra être passée. L’équipe de Maison Bio","question":"Que se passera-t-il entre 1 h et 5 h du matin le 7 mars ?","options":["Les commandes seront enregistrées avec retard","Les commandes seront possibles uniquement par téléphone","Les commandes en ligne seront suspendues pendant la maintenance","Les commandes ne pourront être modifiées qu'après cinq heures"],"correct":"C","explanation":"La maintenance a lieu de 1 h à 5 h ; « aucune commande ne pourra être passée » pendant cette période."},{"number":4,"points":3,"passage":"Annonce à tous les parents : L’école organise une sortie au musée pour les élèves de CE2 le mardi 17 avril. Les enfants doivent apporter un pique-nique, une bouteille d’eau et porter des chaussures confortables. École Les Érables","question":"Quel est l’objectif de ce message ?","options":["Demander aux parents de réserver les billets","Inviter les élèves à choisir leur musée préféré","Annoncer une réunion préparatoire à la sortie","Préciser le matériel nécessaire pour une sortie scolaire"],"correct":"D","explanation":"Le message précise la date de la sortie et ce que les enfants doivent apporter et porter."},{"number":5,"points":9,"passage":"Chers voisins, La fête de quartier annuelle aura lieu le samedi 15 juillet à partir de 16 h dans le parc du square des Lilas. Apportez un plat à partager et votre bonne humeur ! Jeux pour enfants, musique et tombola sont prévus. Le comité de quartier","question":"Pourquoi les voisins sont-ils invités au parc ?","options":["Faire connaissance pendant une fête de quartier","Participer à un repas associatif réservé aux enfants","Se réunir pour préparer la prochaine tombola","Se retrouver pour organiser un nettoyage du parc"],"correct":"A","explanation":"La fête de quartier prévoit un repas partagé, des jeux, de la musique et une tombola : il s’agit d’une célébration locale."},{"number":6,"points":9,"passage":"Annonce : Appartement 2 pièces à louer à partir du 1er septembre. 650 €/mois, charges comprises. Situé au 2e étage avec balcon, à 5 minutes du métro. Idéal pour une personne seule ou un jeune couple. Contact : immo.dubois@email.fr","question":"Quel type de logement est proposé ?","options":["Un studio à louer avec un espace extérieur","Un appartement de deux pièces pour une ou deux personnes","Un logement partagé entre plusieurs colocataires","Un appartement réservé aux familles nombreuses"],"correct":"B","explanation":"L’annonce indique un appartement de deux pièces, « idéal pour une personne seule ou un jeune couple »."},{"number":7,"points":9,"passage":"Bonjour ! Je viens d’avoir une excellente nouvelle : ma sœur attend un bébé ! Toute la famille est ravie, et je suis tellement impatiente de devenir tata ! On organise un petit repas dimanche prochain pour célébrer cette belle annonce. Tu veux venir ? Élodie","question":"Pourquoi Élodie est-elle heureuse ?","options":["Sa sœur prépare une fête d'anniversaire","Elle vient d'avoir un enfant","Elle va bientôt devenir tante","Elle retrouve sa sœur après un voyage"],"correct":"C","explanation":"Élodie annonce que sa sœur « attend un bébé » et qu’elle est impatiente de devenir tante."},{"number":8,"points":9,"passage":"Offre d’emploi – Assistant(e) administratif(ve) Entreprise locale recherche un(e) assistant(e) à mi-temps pour assurer l’accueil, la gestion des appels et le traitement des courriels. Expérience souhaitée, maîtrise de Word et Excel exigée. Envoyer CV à : emploi@bureauplus.fr","question":"Quel profil l’entreprise cherche-t-elle ?","options":["Une personne chargée uniquement des appels","Un responsable de recrutement à temps plein","Un spécialiste de la communication numérique","Un assistant administratif à l'aise avec la bureautique"],"correct":"D","explanation":"Le poste d’assistant administratif exige la maîtrise de Word et Excel, des outils bureautiques."},{"number":9,"points":9,"passage":"Invitation spéciale : Participez à notre soirée de réseautage pour les jeunes professionnels, jeudi 12 octobre à 18 h, au café Connect. Venez rencontrer des entrepreneurs, échanger des idées et élargir votre réseau. Entrée gratuite avec inscription en ligne.","question":"Quel est l’objectif principal de cet événement ?","options":["Faire des rencontres dans un cadre professionnel","Obtenir un entretien d'embauche auprès des invités","Présenter un programme de formation diplômante","Réserver un espace de travail au café"],"correct":"A","explanation":"La soirée permet de « rencontrer des entrepreneurs » et d’« élargir votre réseau »."},{"number":10,"points":9,"passage":"Chers amis, Cette année encore, nous organisons une collecte pour aider les familles en difficulté avant la rentrée. Vous pouvez déposer fournitures scolaires et vêtements en bon état à la mairie avant le 25 août. Merci pour votre générosité ! Association Entraide locale","question":"Quel est le but de cette collecte ?","options":["Collecter des dons pour un voyage des élèves","Aider les familles à préparer la rentrée scolaire","Financer une activité de loisirs à l'école","Réunir les familles pour une fête de quartier"],"correct":"B","explanation":"La collecte de fournitures et de vêtements aide les familles en difficulté « avant la rentrée »."},{"number":11,"points":15,"passage":"Cher Antoine, Je t’écris depuis le petit village de Kpalimé, au Togo, où je participe à un programme de volontariat depuis deux semaines. Nos journées sont bien remplies : nous aidons les instituteurs dans une école primaire, et l’après-midi, nous organisons des ateliers de lecture et d’hygiène pour les enfants. La chaleur est intense, mais l’ambiance est incroyable ! Je loge chez une famille locale très accueillante, et j’ai déjà goûté des plats typiques comme le fufu et l’igname pilée. Je prends beaucoup de photos et je t’enverrai un album à mon retour. À bientôt, Camille","question":"Pourquoi Camille est-elle au Togo ?","options":["Pour suivre une formation à l'université","Pour préparer un séjour touristique dans le pays","Pour participer bénévolement à un projet scolaire","Pour mener une enquête sur les entreprises locales"],"correct":"C","explanation":"Camille participe à un volontariat dans une école et organise des ateliers de lecture et d’hygiène."},{"number":12,"points":15,"passage":"Info aux parents : Nous vous informons qu’un mouvement de grève touchera l’ensemble des écoles primaires de la ville le jeudi 14 décembre. Il n’y aura ni cours, ni accueil périscolaire, ni cantine ce jour-là. Merci de prendre vos dispositions. Un service minimum d’accueil sera assuré à l’école Voltaire pour les enfants dont les deux parents travaillent et qui n’ont aucune solution de garde. Direction des affaires scolaires","question":"Quelle conséquence aura cette grève pour les familles ?","options":["Certains enfants suivront les cours dans une autre école","Les repas seront maintenus malgré l'arrêt des cours","Tous les élèves pourront être accueillis normalement","Des solutions d'accueil limitées seront prévues sous conditions"],"correct":"D","explanation":"Les cours et les services habituels sont supprimés. Seuls les enfants répondant aux conditions indiquées peuvent bénéficier de l’accueil à l’école Voltaire."},{"number":13,"points":15,"passage":"Technologie – Transports Depuis quelques semaines, des navettes électriques sans conducteur circulent dans certains quartiers de Lyon. Ces véhicules autonomes peuvent transporter jusqu’à 10 personnes et s’arrêtent à la demande, grâce à une application mobile. Ils roulent à faible vitesse, ce qui les rend très sûrs, notamment dans les zones piétonnes. Ce projet pilote est mené en partenariat avec la métropole de Lyon pour tester de nouvelles solutions de mobilité plus écologiques. Des questionnaires sont proposés aux passagers à la fin de chaque trajet pour recueillir leur avis sur le confort et la fiabilité du service.","question":"Que teste la ville de Lyon avec ce projet ?","options":["Des navettes autonomes écologiques","Une nouvelle ligne de métro souterraine","Des bus électriques avec chauffeur","Des vélos électriques à partager"],"correct":"A","explanation":"Les navettes sont électriques, « sans conducteur » et testées comme solution de mobilité écologique."},{"number":14,"points":15,"passage":"Cher Louis, Tu ne devineras jamais où je suis ! J’étais censée passer le week-end à Nantes, mais mon train a été annulé à cause d’un problème sur la ligne. J’ai donc pris un bus pour rejoindre une amie à La Rochelle, et nous avons décidé de passer deux jours ici. C’est une très belle ville ! On s’est promenées sur le port, et on a même visité l’aquarium. On profite du soleil et de l’air marin. Finalement, ce changement de programme était une bonne surprise. Je repars mardi matin. À très vite, Inès","question":"Dans quelle ville Inès a-t-elle passé le week-end ?","options":["À Nantes","À La Rochelle","À Paris","À Bordeaux"],"correct":"B","explanation":"Le train pour Nantes ayant été annulé, Inès a rejoint une amie à La Rochelle et y a passé deux jours."},{"number":15,"points":15,"passage":"Écologie – Actualité Le gouvernement a annoncé la mise en place progressive d’une interdiction des emballages plastiques à usage unique dans les commerces de proximité. Dès janvier prochain, les sacs plastiques seront bannis des boulangeries, des boucheries et des primeurs. Les clients devront venir avec leurs propres contenants, ou utiliser des sacs réutilisables en tissu ou en papier. Cette décision vise à réduire considérablement la production de déchets non recyclables, alors que la pollution plastique continue d’augmenter dans les milieux naturels. Des campagnes d'information sont prévues pour accompagner les professionnels et les consommateurs dans cette transition.","question":"Quel est l’objectif principal de cette mesure ?","options":["Favoriser la consommation locale","Protéger les commerces indépendants","Réduire l’utilisation du plastique jetable","Améliorer l’hygiène des produits vendus"],"correct":"C","explanation":"L’interdiction vise à « réduire considérablement la production de déchets non recyclables » liés aux plastiques à usage unique."},{"number":16,"points":15,"passage":"Vie locale Ce samedi, la maison des associations accueille un forum sur le thème “Grandir à l’ère numérique”. Parents, enseignants, psychologues et spécialistes du numérique interviendront pour échanger sur l’impact des écrans dans la vie des enfants et des adolescents. Des ateliers sont aussi prévus pour les jeunes, afin de leur apprendre à reconnaître les fausses informations, à limiter leur temps d’écran, et à mieux gérer les réseaux sociaux. L’entrée est libre, mais les places sont limitées. Renseignements sur le site de la mairie.","question":"Quel est le thème principal de cet événement ?","options":["L’impact de la technologie sur la santé physique","Les méthodes pour améliorer la mémoire","Le développement de logiciels éducatifs","L’éducation des jeunes au numérique"],"correct":"D","explanation":"Le forum « Grandir à l’ère numérique » porte sur les écrans, les fausses informations et les réseaux sociaux chez les jeunes."},{"number":17,"points":15,"passage":"Message d’Aurélie à son frère : Devine quoi ! J’ai enfin quitté mon travail au bureau pour me lancer dans ma passion : la pâtisserie. Je me suis inscrite à une formation intensive de six mois à Lyon pour apprendre les bases. Je me lève tôt, je finis tard, mais je n’ai jamais été aussi heureuse. Mon objectif est d’ouvrir ma propre boutique d’ici un an. Je commence à créer mes premières recettes, et mes collègues de cours sont super motivants. Tu peux venir goûter mes créations quand tu veux !","question":"Qu’a décidé de faire Aurélie ?","options":["Faire une reconversion professionnelle","Créer une école de cuisine","Ouvrir une boulangerie traditionnelle","Déménager à l’étranger"],"correct":"A","explanation":"Aurélie a quitté son emploi de bureau pour se former à la pâtisserie : elle change de métier."},{"number":18,"points":15,"passage":"Avis aux usagers du réseau TER À partir du 15 avril, le train de 7 h 22 entre Grenoble et Chambéry sera supprimé en raison de travaux sur la voie. Les voyageurs sont invités à prendre le train de 7 h 55, ou à utiliser les cars de substitution mis en place. Des retards sont également à prévoir sur les lignes voisines pendant la durée des travaux. Des annonces seront faites en gare, et les informations seront mises à jour chaque jour sur le site TER.","question":"Qu’indique cet avis aux voyageurs ?","options":["Un changement de gare de départ","La suppression d’un train du matin","L’ajout d’un nouveau train en matinée","La gratuité des trains pendant les travaux"],"correct":"B","explanation":"L’avis annonce que « le train de 7 h 22 […] sera supprimé » à partir du 15 avril."},{"number":19,"points":15,"passage":"Société – Médias Selon une étude récente, près de 40 % des adultes de moins de 30 ans s’informent exclusivement via les réseaux sociaux. Ce phénomène inquiète certains experts, car ces plateformes mélangent contenus d’information, opinions personnelles, publicités, et fausses nouvelles. De plus, les algorithmes montrent souvent aux utilisateurs les contenus qui renforcent leurs idées déjà existantes, ce qui limite l’ouverture d’esprit. Des associations proposent désormais des ateliers d’éducation aux médias, notamment dans les lycées et les universités.","question":"Quel problème est soulevé dans cet article ?","options":["Le manque de connexion dans les zones rurales","Le coût croissant des abonnements presse","Les dangers d’une information non vérifiée en ligne","L’augmentation du temps passé à lire les journaux papier"],"correct":"C","explanation":"Le texte évoque le mélange d’informations, d’opinions, de publicités et de fausses nouvelles sur les réseaux sociaux."},{"number":20,"points":21,"passage":"La municipalité de Saint-Alban a lancé un programme incitatif pour encourager les habitants à installer des panneaux solaires sur leurs toits. Toute personne qui s’inscrit avant le 30 septembre bénéficiera d’une subvention couvrant jusqu’à 40 % des frais d’installation. En plus de l’aide financière, des ateliers d’information sont organisés pour expliquer les avantages environnementaux et économiques de cette transition. Le maire espère ainsi faire de Saint-Alban un exemple en matière d’énergie renouvelable. Il espère aussi réduire à terme les factures d’électricité de la population locale et contribuer aux objectifs nationaux de réduction carbone.","question":"Quelle est l’intention principale de la municipalité ?","options":["Promouvoir une réduction de la consommation d’électricité","Accroître l’usage des énergies fossiles","Réduire le nombre de toitures anciennes","Encourager les résidents à adopter l’énergie solaire"],"correct":"D","explanation":"Le programme subventionne l’installation de panneaux solaires afin d’encourager l’énergie renouvelable."},{"number":21,"points":21,"passage":"Dans une petite ville du sud de la France, une école a décidé de remplacer tous les manuels papier par des tablettes numériques. L’objectif est de moderniser les méthodes d’enseignement tout en réduisant le poids des cartables. Certains parents s’inquiètent de l’exposition prolongée des enfants aux écrans, mais les enseignants affirment que les contenus numériques permettent une approche plus interactive et personnalisée de l’apprentissage. Un suivi statistique des résultats sera aussi mis en place pour évaluer l’impact réel sur les performances scolaires.","question":"Quel est le principal changement apporté à cette école ?","options":["L’introduction de tablettes pour remplacer les livres","La suppression des devoirs à domicile","La réduction du nombre d’élèves par classe","La mise en place d’activités sportives"],"correct":"A","explanation":"L’école « a décidé de remplacer tous les manuels papier par des tablettes numériques »."},{"number":22,"points":21,"passage":"La Bibliothèque Nationale a récemment lancé une campagne de collecte de livres rares auprès du public. L’idée est de constituer un fonds de documents historiques afin de préserver la mémoire culturelle. Les particuliers peuvent proposer des ouvrages anciens, qui seront ensuite évalués par une équipe de spécialistes. En échange, leur nom sera mentionné dans les archives numériques et ils recevront un certificat de contribution. L’initiative a déjà permis de rassembler plus de 800 ouvrages datant d’avant 1900.","question":"Quel est le but de cette campagne ?","options":["Enrichir les collections personnelles des donateurs","Préserver des livres historiques pour les générations futures","Créer un musée de livres contemporains","Revendre les livres rares à des collectionneurs privés"],"correct":"B","explanation":"La collecte constitue un fonds de documents historiques pour « préserver la mémoire culturelle »."},{"number":23,"points":21,"passage":"Le chef étoilé Alain Morel a décidé d’ouvrir un restaurant gastronomique 100 % végétarien, une première pour lui. Cette décision s’inscrit dans une volonté de proposer une cuisine durable sans sacrifier le goût. Dans ses plats, il utilise des légumes oubliés, des légumineuses locales et des épices rares. Le restaurant connaît un succès inattendu, attirant même des amateurs de viande curieux de cette nouvelle expérience culinaire. Il envisage déjà d’ouvrir une deuxième adresse dans une autre grande ville européenne.","question":"Quelle orientation a pris le chef Alain Morel ?","options":["Il a arrêté la cuisine pour se consacrer à l’agriculture","Il a ouvert une école de cuisine spécialisée en viande","Il propose une cuisine végétarienne de haute qualité","Il se consacre uniquement à la pâtisserie"],"correct":"C","explanation":"Le chef ouvre un restaurant gastronomique « 100 % végétarien » sans sacrifier le goût."},{"number":24,"points":21,"passage":"Depuis plusieurs années, la ville de Rouen est confrontée à une augmentation du nombre de vélos dans les rues, ce qui provoque parfois des conflits entre cyclistes et piétons. Pour remédier à cela, la mairie a décidé d’élargir certaines voies piétonnes et d’installer des pistes cyclables séparées. Une campagne de sensibilisation a également été lancée pour rappeler à chacun les règles de bonne conduite en ville. Les premières évaluations montrent déjà une baisse des incidents signalés.","question":"Quelle mesure la ville a-t-elle prise pour réduire les conflits ?","options":["Interdire les vélos dans le centre-ville","Créer des zones de circulation exclusivement piétonnes","Limiter le nombre de vélos autorisés","Séparer les pistes pour piétons et cyclistes"],"correct":"D","explanation":"La mairie installe « des pistes cyclables séparées » et élargit certaines voies piétonnes."},{"number":25,"points":21,"passage":"Une étude menée par l’Institut de Santé Publique montre que près d’un tiers des Français dorment moins de six heures par nuit. Ce manque de sommeil chronique a des répercussions importantes sur la concentration, la mémoire et le moral. Les chercheurs recommandent d’adopter une routine régulière, de limiter les écrans en soirée et d’éviter les boissons stimulantes après 17h. D’après eux, un sommeil réparateur devrait durer au moins sept heures pour les adultes.","question":"Que souligne cette étude ?","options":["Le manque de sommeil a des effets dans plusieurs domaines","Les difficultés de sommeil touchent principalement la vie professionnelle","Le repos quotidien suffit toujours à prévenir la fatigue","Les habitudes alimentaires expliquent l'ensemble des problèmes"],"correct":"A","explanation":"Le manque de sommeil a des effets sur « la concentration, la mémoire et le moral »."},{"number":26,"points":21,"passage":"Clémence a toujours rêvé d’écrire un roman. Après avoir suivi un atelier d’écriture en ligne pendant six mois, elle a terminé son premier manuscrit. Encouragée par les retours positifs de ses pairs, elle a décidé de l’envoyer à plusieurs maisons d’édition. Quelques semaines plus tard, elle a reçu une proposition de contrat pour publication. Son livre paraîtra dans quelques mois, et elle espère qu’il trouvera son public. Elle envisage même de commencer un second tome.","question":"Quel est le sujet principal de ce texte ?","options":["Une romancière choisit de travailler dans une maison d'édition","Une passionnée parvient à concrétiser un projet d'écriture","Les lecteurs participent à la rédaction d'un roman","Une formation à distance est organisée pour les éditeurs"],"correct":"B","explanation":"Clémence rêvait d’écrire un roman ; elle termine son manuscrit et obtient un contrat de publication."},{"number":27,"points":21,"passage":"Le Mont-Blanc, plus haut sommet d’Europe occidentale, attire chaque été des milliers d’alpinistes amateurs. Face à la hausse du nombre d’accidents, les autorités locales ont mis en place un système de réservation obligatoire et des contrôles renforcés de l’équipement. Cette initiative vise à responsabiliser les randonneurs et à préserver l’environnement fragile de la montagne. Un guide de bonnes pratiques a aussi été distribué aux visiteurs avant l’ascension.","question":"Pourquoi les autorités ont-elles instauré une réservation obligatoire ?","options":["Répartir les visiteurs selon leur lieu de résidence","Réserver la montagne aux alpinistes les plus expérimentés","Limiter les risques tout en préservant le milieu naturel","Organiser le passage des groupes en fonction de leur matériel"],"correct":"C","explanation":"Les réservations et les contrôles répondent aux accidents et visent aussi à préserver l’environnement fragile de la montagne."},{"number":28,"points":21,"passage":"Chaque année, la ville de Nantes organise une « nuit des musées » durant laquelle tous les musées ouvrent gratuitement leurs portes de 18h à minuit. Des spectacles vivants, des visites guidées, et des ateliers interactifs sont proposés. L’événement attire aussi bien des familles que des touristes de passage, et vise à rendre la culture accessible à tous. L’an dernier, plus de 20 000 personnes y ont participé, un record pour la ville.","question":"Quel est le but de la nuit des musées ?","options":["Accueillir davantage de visiteurs dans les musées payants","Réserver les événements nocturnes aux habitants","Faire connaître de nouveaux lieux de spectacles","Favoriser l'accès à des activités culturelles gratuites"],"correct":"D","explanation":"Les musées ouvrent gratuitement et l’événement « vise à rendre la culture accessible à tous »."},{"number":29,"points":21,"passage":"La pollution lumineuse est un phénomène de plus en plus étudié par les scientifiques. Dans certaines régions, l’éclairage nocturne excessif perturbe le cycle de sommeil des animaux et empêche l’observation astronomique. Plusieurs communes ont commencé à éteindre ou réduire l’intensité des lampadaires après 23h pour retrouver un ciel nocturne plus naturel. Cela permet aussi de réduire la consommation d’énergie et de faire des économies budgétaires.","question":"Quelles conséquences sont évoquées à propos de la pollution lumineuse ?","options":["Elle modifie le comportement de certains animaux et la visibilité du ciel","Elle perturbe la circulation de certaines espèces marines","Elle réduit la durée des journées en zone urbaine","Elle améliore les conditions d'observation nocturne"],"correct":"A","explanation":"L’éclairage excessif perturbe le sommeil des animaux et « empêche l’observation astronomique »."},{"number":30,"points":26,"passage":"Les océans couvrent plus de 70 % de la surface de la Terre et jouent un rôle essentiel dans la régulation du climat. Ils absorbent une grande partie du dioxyde de carbone émis par les activités humaines. Cependant, cette absorption entraîne l’acidification des eaux marines, ce qui menace les récifs coralliens et la biodiversité. Des scientifiques tirent la sonnette d’alarme depuis plusieurs années. Ils soulignent qu’il est urgent de réduire les émissions pour préserver les écosystèmes marins.","question":"Que déduit-on sur les océans dans ce texte ?","options":["Les ressources marines sont réparties de manière inégale","Les activités humaines fragilisent l'équilibre des océans","La vie océanique s'adapte sans difficulté au réchauffement","Le rôle des océans dans le climat reste secondaire"],"correct":"B","explanation":"Le CO₂ émis par les activités humaines acidifie les eaux et menace les récifs et la biodiversité."},{"number":31,"points":26,"passage":"Dans une école expérimentale, les élèves n’ont pas d’horaires fixes ni de manuels imposés. Ils choisissent leurs sujets d’étude selon leurs intérêts. Les enseignants jouent le rôle de guides, les aidant à approfondir leurs recherches et à formuler leurs propres questions. Ce modèle éducatif attire l’attention de nombreux pédagogues en quête d’alternatives au système traditionnel. Les résultats des élèves à long terme sont en cours d’évaluation.","question":"Qu’indique ce texte sur cette école ?","options":["Les élèves travaillent avec des manuels imposés","Les résultats confirment déjà la supériorité du modèle","Le modèle intéresse des visiteurs malgré ses incertitudes","Les enseignants dirigent chaque projet des élèves"],"correct":"C","explanation":"Le modèle « attire l’attention de nombreux pédagogues ». Ses résultats à long terme sont encore en cours d’évaluation."},{"number":32,"points":26,"passage":"La ville de Bordeaux a récemment transformé une ancienne voie ferrée en promenade urbaine verte. Cet espace, long de plusieurs kilomètres, est aujourd’hui planté d’arbres et de fleurs locales. Les habitants s’y promènent, y font du vélo et participent à des ateliers de jardinage. Ce projet, qui favorise la biodiversité et le bien-être, inspire d’autres villes européennes à lancer des initiatives similaires. Une enquête a montré une forte hausse de la satisfaction des résidents.","question":"Qu’apprend-on sur ce projet ?","options":["Le projet remplace les espaces verts par une nouvelle voie ferrée","La ville privilégie la circulation ferroviaire sur l'accès à pied","Le quartier devient une destination strictement touristique","La promenade améliore l'environnement et l'usage du quartier"],"correct":"D","explanation":"La promenade verte favorise « la biodiversité et le bien-être » et augmente la satisfaction des habitants."},{"number":33,"points":26,"passage":"<< Les Brumes du Nord >> est un roman d’aventure situé dans une Scandinavie imaginaire. L’intrigue repose sur une légende ancestrale, mais peine à captiver le lecteur. Les personnages manquent parfois de nuances, bien que certains passages soient bien écrits. Le style de l’auteur est fluide, mais certains critiques notent un manque de suspense. Malgré cela, le livre reste plaisant pour les amateurs de récits nordiques.","question":"Sur quoi porte la critique négative faite à ce roman ?","options":["Le récit peine à maintenir l'intérêt du lecteur","Les personnages secondaires manquent de réalisme","Le cadre historique semble insuffisamment documenté","Le style d'écriture empêche de comprendre les dialogues"],"correct":"A","explanation":"Le texte relève un « manque de suspense » : la critique porte sur l’absence de tension dans l’intrigue."},{"number":34,"points":26,"passage":"Une enquête sociologique récente révèle que les jeunes adultes privilégient aujourd’hui les expériences plutôt que les possessions matérielles. Voyager, assister à des concerts ou pratiquer une activité nouvelle sont perçus comme plus enrichissants que l’achat d’objets. Les réseaux sociaux renforcent cette tendance, en valorisant les récits personnels et les découvertes. Cette évolution soulève des questions sur les comportements économiques futurs et la définition du succès.","question":"Que montre cette enquête ?","options":["Les jeunes privilégient les objets faciles à transporter","Les expériences vécues comptent dans l'épanouissement personnel","Les achats sont considérés comme la principale forme de réussite","Les jeunes renoncent aux activités collectives"],"correct":"B","explanation":"Les voyages, concerts et nouvelles activités sont perçus comme « plus enrichissants que l’achat d’objets »."},{"number":35,"points":26,"passage":"Une équipe de chercheurs a étudié la relation entre la musique et la mémoire. Ils ont constaté que les personnes âgées se souvenaient mieux d’un événement si une chanson familière était associée au moment. Ce lien émotionnel semble renforcer les connexions neuronales. Des tests montrent que les malades d’Alzheimer réagissent plus positivement à la musique qu’à d’autres stimuli. Cette découverte ouvre la voie à de nouvelles thérapies non médicamenteuses.","question":"Que démontre cette recherche ?","options":["La mémoire des événements récents progresse chez tous les participants","La musique modifie les souvenirs indépendamment de l'âge","La musique peut faciliter le souvenir grâce aux émotions","Les émotions réduisent systématiquement les troubles de mémoire"],"correct":"C","explanation":"Une chanson familière associée à un événement facilite son souvenir grâce au lien émotionnel."},{"number":36,"points":33,"passage":"Les restaurants végétariens se multiplient dans les grandes villes européennes. Il y a quelques années, ce type d’établissement était encore marginal, fréquenté par une minorité de consommateurs engagés. Aujourd’hui, la situation a changé. De nombreuses personnes consomment moins de viande, parfois pour des raisons de santé, parfois pour des préoccupations environnementales ou éthiques. Les chefs s’adaptent à cette tendance et proposent des plats créatifs, riches en saveurs, capables de convaincre même les plus fervents amateurs de viande. Le succès de ces établissements repose aussi sur la qualité des produits utilisés : légumes bio, circuits courts, recettes de saison. Ce mouvement entraîne une revalorisation des légumes, longtemps considérés comme simples accompagnements. En rendant la cuisine végétale attrayante et gourmande, les restaurants végétariens participent à une véritable révolution culinaire. Ils attirent désormais une clientèle variée et fidèle.","question":"Quel constat peut-on faire sur les restaurants végétariens ?","options":["La cuisine végétarienne devient moins diverse avec son succès","Les légumes restent cantonnés aux accompagnements","Les nouveaux restaurants s'adressent à un public très restreint","La gastronomie végétarienne renouvelle l'image des légumes"],"correct":"D","explanation":"Les légumes sont revalorisés : ils passent de simples accompagnements à une cuisine créative et gourmande."},{"number":37,"points":33,"passage":"Le télétravail, autrefois réservé à quelques secteurs très spécialisés, s’est largement démocratisé depuis la crise sanitaire. Beaucoup d’entreprises ont adopté un fonctionnement hybride, mêlant présence au bureau et travail à distance. Les salariés apprécient cette souplesse, qui leur permet de mieux concilier vie professionnelle et personnelle. Mais le télétravail n’est pas sans inconvénient : isolement social, difficulté à séparer vie privée et vie professionnelle, surcharge de travail… Les managers doivent repenser leurs méthodes de suivi et de communication pour maintenir la cohésion de leurs équipes. D’un autre côté, certaines entreprises y voient une opportunité de réduire leurs coûts immobiliers. Il est donc probable que ce mode d’organisation s’installe durablement. Cependant, il faudra encore du temps pour trouver un équilibre adapté à tous les types de métiers et de personnalités.","question":"Quel aspect du télétravail est mis en avant ici ?","options":["Le télétravail oblige les entreprises à réorganiser leur fonctionnement","Le télétravail diminue l'ensemble des échanges professionnels","Le télétravail repose sur un équipement identique pour chacun","Le télétravail remplace durablement toute présence au bureau"],"correct":"A","explanation":"Les managers doivent « repenser leurs méthodes de suivi et de communication » et trouver un équilibre adapté."},{"number":38,"points":33,"passage":"Dans certaines écoles de campagne, les enseignants doivent faire preuve d’une grande polyvalence. Il n’est pas rare qu’un seul professeur s’occupe de plusieurs niveaux dans une même salle de classe. Cela demande une organisation rigoureuse et beaucoup de créativité. Les élèves, bien que très jeunes, apprennent à être autonomes et à gérer leur temps. Cette configuration favorise également l’entraide entre les âges. Toutefois, ce modèle a ses limites : les enseignants sont parfois débordés, et l’accès aux ressources pédagogiques reste limité dans les zones rurales. L’État tente de soutenir ces écoles à travers des plans d’investissement et la mise à disposition de matériel numérique. Néanmoins, les différences avec les établissements urbains persistent. De nombreux parents restent attachés à ce type d’école, estimant qu’il transmet des valeurs de proximité, d’écoute et de respect du rythme de chaque élève.","question":"Quelle particularité des écoles rurales est soulignée ?","options":["Les écoles rurales imposent des classes de taille plus importante","La diversité des âges favorise entraide et autonomie","Les élèves de ces écoles travaillent souvent sans enseignant","Les petites écoles refusent les projets communs entre niveaux"],"correct":"B","explanation":"Les élèves apprennent l’autonomie et la gestion du temps ; la classe favorise « l’entraide entre les âges »."},{"number":39,"points":33,"passage":"L’usage des trottinettes électriques en ville a connu une explosion ces dernières années. D’abord perçues comme un gadget urbain, elles sont devenues un véritable moyen de transport, surtout chez les jeunes actifs. Leur coût relativement bas, la facilité d’utilisation, et la possibilité d’éviter les embouteillages expliquent en partie leur succès. Cependant, leur présence massive sur les trottoirs soulève des inquiétudes. Des accidents se produisent régulièrement, parfois graves, impliquant piétons, cyclistes ou automobilistes. De nombreuses municipalités ont réagi en instaurant des règles strictes : interdiction sur les trottoirs, limitation de la vitesse, port du casque recommandé, voire retrait de certaines entreprises de location. Cette régulation vise à encadrer un phénomène qui, mal maîtrisé, pourrait nuire à la sécurité et à la cohabitation en ville. L’avenir des trottinettes électriques dépendra donc de leur intégration harmonieuse dans l’espace urbain.","question":"Quel est le principal enjeu lié aux trottinettes électriques ?","options":["Les coûts des trajets en trottinette par rapport au bus","Le remplacement des transports publics par ces véhicules","L'encadrement de leur usage pour la sécurité en ville","La nécessité d'en augmenter la vitesse en centre-ville"],"correct":"C","explanation":"Les règles sur la circulation et la vitesse cherchent à assurer la sécurité et la cohabitation dans l’espace urbain."}]}$paper$::jsonb),
('tcf-reading-05','tcf-reading-2026-11-editorial-v4',$paper${"id":"tcf-reading-05","version":"tcf-reading-2026-11-editorial-v4","title":"TCF Reading · Test 05","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Déposez les piles usagées dans la boîte de l'accueil. Les ampoules doivent être apportées au magasin de bricolage voisin.\n\nUn agent peut expliquer les autres points de collecte. Merci de ne rien laisser à côté de la boîte.","question":"Où déposer les piles ?","options":["Dans le magasin prévu pour les ampoules","À côté de la boîte de collecte","Dans le bac des déchets en papier","Dans la boîte située à l'accueil"],"correct":"D","explanation":"Le passage indique : « Déposez les piles usagées dans la boîte de l'accueil. Les ampoules doivent être apportées au magasin de bricolage voisin. » Cela justifie la réponse : À l'accueil."},{"number":2,"points":3,"passage":"La collecte des feuilles aura lieu jeudi. Les sacs en plastique ne seront pas acceptés ; utilisez les sacs en papier distribués en mairie.\n\nLes distributions de sacs se font aux horaires habituels.","question":"Quel contenant faut-il utiliser ?","options":["Les sacs en papier remis par la mairie","Les sacs compostables du commerce","Les sacs plastiques de collecte","Les grands sacs de déchets ménagers"],"correct":"A","explanation":"Le passage indique : « La collecte des feuilles aura lieu jeudi. Les sacs en plastique ne seront pas acceptés ; utilisez les sacs en papier distribués en mairie. » Cela justifie la réponse : Un sac en papier."},{"number":3,"points":3,"passage":"En période de sécheresse, l'arrosage des pelouses est suspendu. Les jeunes arbres peuvent recevoir de l'eau avant huit heures.\n\nDes contrôles auront lieu pendant toute la période annoncée par la commune.","question":"Quel arrosage reste permis ?","options":["Arroser les jeunes arbres avant huit heures","Arroser les jeunes arbres en journée","Arroser les pelouses tôt le matin","Arroser les pelouses après le coucher du soleil"],"correct":"A","explanation":"Le passage indique : « En période de sécheresse, l'arrosage des pelouses est suspendu. Les jeunes arbres peuvent recevoir de l'eau avant huit heures. » Cela justifie la réponse : Celui des jeunes arbres tôt le matin."},{"number":4,"points":3,"passage":"Le café accepte vos tasses réutilisables propres. Les couvercles jetables ne sont plus fournis automatiquement ; demandez-en un si nécessaire.\n\nL'équipe souhaite réduire les petits déchets emportés après chaque vente. Cette organisation sera évaluée avec les clients au cours du mois prochain.","question":"Quelle nouvelle habitude est proposée ?","options":["Utiliser des tasses fournies par le café","Rapporter les couvercles après usage","Apporter une tasse à faire laver sur place","Apporter sa tasse réutilisable propre"],"correct":"D","explanation":"Le passage indique : « Le café accepte vos tasses réutilisables propres. Les couvercles jetables ne sont plus fournis automatiquement ; demandez-en un si nécessaire. » Cela justifie la réponse : Utiliser sa propre tasse propre."},{"number":5,"points":9,"passage":"Demain, apportons chacun une boîte pour le pique-nique. Je préparerai les boissons dans une grande gourde ; inutile d'acheter des bouteilles individuelles.\n\nNous pourrons tout rapporter après le repas au lieu de remplir les poubelles du parc. J'ai aussi prévu des couverts que nous laverons chez moi.","question":"Que cherche à limiter ce message ?","options":["Réduire les portions servies au pique-nique","Éviter de transporter des boissons chaudes","Réduire le nombre de plats préparés","Limiter les contenants à usage unique"],"correct":"D","explanation":"Le passage indique : « Demain, apportons chacun une boîte pour le pique-nique. Je préparerai les boissons dans une grande gourde ; inutile d'acheter des bouteilles individuelles. » Cela justifie la réponse : Les contenants jetables."},{"number":6,"points":9,"passage":"L'atelier réparation accepte les grille-pain et les lampes. Les appareils à gaz sont exclus, car les bénévoles n'ont pas la qualification nécessaire.\n\nUn bénévole examinera d'abord l'objet pour vérifier si l'intervention est possible. Les réparations complexes seront orientées vers un professionnel du secteur.","question":"Pourquoi certains appareils sont-ils refusés ?","options":["Les bénévoles ne sont pas habilités à intervenir sur le gaz","Les réparations de ces appareils demandent plus de temps","La collecte des pièces de rechange est trop coûteuse","L'atelier réserve leur réparation aux séances du soir"],"correct":"A","explanation":"Le passage indique : « L'atelier réparation accepte les grille-pain et les lampes. Les appareils à gaz sont exclus, car les bénévoles n'ont pas la qualification nécessaire. » Cela justifie la réponse : Pour respecter les compétences disponibles."},{"number":7,"points":9,"passage":"Je laisse une partie du jardin sans tonte cette année. Je garderai seulement un passage court pour accéder au cabanon.\n\nCe sera intéressant de voir quelles plantes apparaissent et si les insectes reviennent. Je prendrai quelques photographies pour comparer les changements au fil de la saison.","question":"Comment le jardin sera-t-il entretenu ?","options":["Le passage vers le cabanon restera non tondu","La tonte aura lieu uniquement en fin de saison","Une partie du jardin restera sans tonte","Les plantes spontanées seront retirées avant l'été"],"correct":"C","explanation":"Le passage indique : « Je laisse une partie du jardin sans tonte cette année. Je garderai seulement un passage court pour accéder au cabanon. » Cela justifie la réponse : Avec des zones volontairement non tondues."},{"number":8,"points":9,"passage":"La visite du centre de tri est gratuite. Les enfants de moins de huit ans ne peuvent pas y participer pour des raisons de sécurité.\n\nLes groupes seront accompagnés dans les zones autorisées.","question":"Quelle condition concerne les enfants ?","options":["Participer uniquement avec un groupe scolaire","Venir accompagné même avant huit ans","Avoir suivi une initiation au tri sélectif","Avoir au moins huit ans pour la visite"],"correct":"D","explanation":"Le passage indique : « La visite du centre de tri est gratuite. Les enfants de moins de huit ans ne peuvent pas y participer pour des raisons de sécurité. » Cela justifie la réponse : Avoir au moins huit ans."},{"number":9,"points":9,"passage":"Chers membres, les gobelets consignés devront être rapportés avant la fermeture du festival pour récupérer la consigne. Ils ne sont pas des cadeaux promotionnels.\n\nLe point de retour se trouve près de la sortie principale.","question":"Que faut-il faire pour récupérer la somme déposée ?","options":["Rapporter le gobelet après la fermeture","Rapporter le gobelet avant la fermeture","Remettre le gobelet à l'entrée du site","Rendre le gobelet lors d'un autre festival"],"correct":"B","explanation":"Le passage indique : « Chers membres, les gobelets consignés devront être rapportés avant la fermeture du festival pour récupérer la consigne. Ils ne sont pas des cadeaux promotionnels. » Cela justifie la réponse : Rapporter le gobelet à temps."},{"number":10,"points":9,"passage":"Le concours de jardins récompense cette année les pratiques économes en eau. La présence de fleurs rares ne rapporte pas de points supplémentaires.\n\nLes participants présenteront leurs choix au jury. Des photographies prises à différentes périodes permettront aussi d'expliquer l'évolution du jardin et les difficultés rencontrées.","question":"Quel critère est privilégié ?","options":["La variété des végétaux présentés","Une utilisation économe de l'eau","Le caractère rare des fleurs","La qualité des photographies du jardin"],"correct":"B","explanation":"Le passage indique : « Le concours de jardins récompense cette année les pratiques économes en eau. La présence de fleurs rares ne rapporte pas de points supplémentaires. » Cela justifie la réponse : La gestion de l'eau."},{"number":11,"points":15,"passage":"Une épicerie propose des produits en vrac. Les clients peuvent apporter leurs contenants, qui sont pesés vides avant d'être remplis.\n\nLe personnel retire ensuite ce poids du montant utilisé pour calculer le prix. Une démonstration est proposée aux nouveaux clients, car plusieurs personnes hésitent à se servir seules lors de leur première visite. Le magasin accepte des boîtes de tailles différentes, à condition qu'elles soient propres et adaptées au produit choisi. Il souhaite rendre cette formule simple sans promettre que tous les aliments pourront être transportés dans n'importe quel récipient. Les tarifs restent affichés au même endroit.","question":"Pourquoi pèse-t-on le contenant vide ?","options":["Pour fixer le prix de chaque bocal","Pour vérifier la capacité du récipient","Pour déduire le poids du récipient du prix","Pour contrôler la quantité de produit admise"],"correct":"C","explanation":"Le passage indique : « Une épicerie propose des produits en vrac. Les clients peuvent apporter leurs contenants, qui sont pesés vides avant d'être remplis. » Cela justifie la réponse : Pour ne facturer que le produit."},{"number":12,"points":15,"passage":"Des élèves recensent les oiseaux près de leur école chaque vendredi. Ils observent au même endroit et à la même heure pour rendre les relevés comparables.\n\nLes élèves notent la météo et le nombre de personnes présentes, afin de conserver une trace des circonstances. Une association vérifie les espèces difficiles à identifier sur les photographies. L'école veut surtout apprendre à observer avec régularité, plutôt qu'annoncer un résultat spectaculaire après une seule séance.","question":"Pourquoi répéter les mêmes conditions ?","options":["Pour observer un plus grand nombre d'espèces","Pour éviter de consigner les conditions météo","Pour répartir les élèves dans différents lieux","Pour rendre les résultats comparables"],"correct":"D","explanation":"Le passage indique : « Des élèves recensent les oiseaux près de leur école chaque vendredi. Ils observent au même endroit et à la même heure pour rendre les relevés comparables. » Cela justifie la réponse : Faciliter la comparaison des observations."},{"number":13,"points":15,"passage":"Un composteur collectif ferme temporairement après des dépôts inadaptés. Les habitants recevront une démonstration avant sa réouverture.\n\nLes erreurs concernaient notamment les emballages et les restes trop volumineux. L'association installera des indications illustrées à proximité du bac et désignera des personnes de contact dans plusieurs immeubles. Les usagers pourront leur poser une question avant de déposer un produit inhabituel. Le comité souhaite que cette interruption serve à améliorer le fonctionnement, sans faire croire qu'un composteur se gère tout seul. Un premier contrôle sera organisé quelques semaines après la reprise.","question":"Quel problème la démonstration doit-elle résoudre ?","options":["Le choix du lieu d'installation du composteur","La récupération des emballages en bon état","Les dépôts de matières inadaptées au compostage","Le transport des déchets vers la déchèterie"],"correct":"C","explanation":"Le passage indique : « Un composteur collectif ferme temporairement après des dépôts inadaptés. Les habitants recevront une démonstration avant sa réouverture. » Cela justifie la réponse : Les erreurs de dépôt."},{"number":14,"points":15,"passage":"La commune remplace ses haies taillées par des espèces locales variées. Elle souhaite offrir des abris à différentes espèces plutôt qu'un décor identique toute l'année.\n\nLes plantations ont été choisies avec une pépinière et une association naturaliste. Certaines fleurissent au printemps, d'autres portent des fruits plus tard. Le calendrier d'entretien tiendra compte des périodes où les animaux utilisent les branches pour se reproduire. Les agents expliquent aux riverains que la haie pourra paraître moins uniforme sans être abandonnée. Une petite visite permettra de découvrir les espèces installées et de comprendre les fonctions recherchées, au-delà de leur seul aspect décoratif.","question":"Quel objectif guide ce remplacement ?","options":["Offrir des habitats à davantage d'espèces","Rendre toutes les haies identiques toute l'année","Réduire le nombre de plantes locales utilisées","Faciliter une taille uniforme à chaque saison"],"correct":"A","explanation":"Le passage indique : « La commune remplace ses haies taillées par des espèces locales variées. Elle souhaite offrir des abris à différentes espèces plutôt qu'un décor identique toute l'année. » Cela justifie la réponse : Favoriser la diversité du vivant."},{"number":15,"points":15,"passage":"Un magasin reprend les vêtements abîmés, mais demande de séparer les articles encore utilisables. Ceux-ci pourront être réemployés plutôt que transformés en fibres.\n\nDes bénévoles vérifient l'état des vêtements avant de les orienter vers les associations partenaires. Une petite couture ou un bouton remplacé permet parfois de remettre rapidement un article en circulation. Les tissus vraiment usés seront regroupés pour un autre traitement. Le magasin souhaite éviter que l'ensemble des dons soit considéré comme une matière indistincte. Il indiquera les résultats de la collecte pour expliquer les volumes réutilisés et ceux qui nécessitent une transformation plus importante.","question":"Pourquoi distinguer les deux catégories ?","options":["Envoyer les tissus encore utilisables au recyclage","Répartir les articles selon le prix d'origine","Conserver la possibilité de réemployer certains vêtements","Écarter les vêtements qui demandent une petite couture"],"correct":"C","explanation":"Le passage indique : « Un magasin reprend les vêtements abîmés, mais demande de séparer les articles encore utilisables. Ceux-ci pourront être réemployés plutôt que transformés en fibres. » Cela justifie la réponse : Préserver la possibilité de réutilisation."},{"number":16,"points":15,"passage":"Une association nettoie les berges sans entrer dans les roselières. Ces zones servent de refuge ; retirer les déchets ne doit pas déranger les oiseaux nicheurs.\n\nLes organisateurs ont préparé un parcours et expliqué les zones à éviter avant le départ. Les sacs seront transportés par les passages déjà fréquentés. Si un déchet se trouve dans un endroit sensible, un responsable décidera comment intervenir plus tard. Les bénévoles comprennent ainsi qu'une action de nettoyage ne se juge pas seulement au nombre de sacs remplis.","question":"Quelle précaution est prise ?","options":["Nettoyer uniquement les berges déjà dégradées","Éviter de perturber les refuges des oiseaux nicheurs","Retirer les plantes aquatiques avant les déchets","Déplacer les nids avant d'accéder aux roselières"],"correct":"B","explanation":"Le passage indique : « Une association nettoie les berges sans entrer dans les roselières. Ces zones servent de refuge ; retirer les déchets ne doit pas déranger les oiseaux nicheurs. » Cela justifie la réponse : Éviter certains habitats pendant le nettoyage."},{"number":17,"points":15,"passage":"Des habitants comparent leurs consommations d'eau après l'installation de mousseurs. Ils relèvent aussi le nombre de personnes présentes pour ne pas attribuer toute variation au matériel.\n\nLes familles comparent des périodes de durée semblable et indiquent les changements de leurs habitudes. Un week-end avec des invités ou une longue absence peut peser sur le résultat. L'association les aide à lire les relevés sans transformer l'expérience en compétition. Elle veut savoir si l'équipement contribue à réduire la consommation dans des conditions ordinaires. Les participants discuteront ensuite des solutions les plus simples à conserver au quotidien, avec ou sans nouvelle installation.","question":"Que veulent-ils éviter ?","options":["Une erreur dans le prix des équipements installés","Attribuer trop vite les variations aux mousseurs","La comparaison de périodes de durée semblable","Le relevé du nombre de personnes dans le foyer"],"correct":"B","explanation":"Le passage indique : « Des habitants comparent leurs consommations d'eau après l'installation de mousseurs. Ils relèvent aussi le nombre de personnes présentes pour ne pas attribuer toute variation au matériel. » Cela justifie la réponse : Une interprétation trop rapide des chiffres."},{"number":18,"points":15,"passage":"Une entreprise propose le prêt de vaisselle pour les fêtes. Les clients la rapportent sale ; le lavage collectif est organisé avec une machine adaptée.\n\nLes lots sont comptés avant chaque retour afin de repérer rapidement une pièce manquante. L'entreprise vérifie aussi que le nettoyage correspond au type de vaisselle proposé. Une fiche explique les horaires et les modalités de transport. Le responsable suivra les quantités réellement réutilisées au cours de la saison, ainsi que les déplacements nécessaires pour assurer les prêts, avant de dresser un bilan plus large.","question":"Quel service est inclus ?","options":["Le nettoyage des pièces après leur retour","La préparation des repas avant la réception","Le dressage des tables pour les invités","La livraison des boissons avec la vaisselle"],"correct":"A","explanation":"Le passage indique : « Une entreprise propose le prêt de vaisselle pour les fêtes. Les clients la rapportent sale ; le lavage collectif est organisé avec une machine adaptée. » Cela justifie la réponse : Le nettoyage après retour."},{"number":19,"points":15,"passage":"Le ramassage des déchets sur une plage se déroule après la marée haute. Les organisateurs vérifient les horaires pour ne pas exposer les participants à la montée des eaux.\n\nUn guide rappelle les limites du parcours et les points de rendez-vous en cas de séparation du groupe. Les zones difficiles d'accès resteront exclues, même si des déchets y sont visibles. Les participants sont invités à porter des chaussures fermées et à ne pas ramasser les objets dangereux à mains nues.","question":"Pourquoi choisir ce moment ?","options":["Pour profiter d'une plage plus accessible au public","Pour limiter le risque lié à la montée des eaux","Pour observer davantage de déchets dans l'eau","Pour prolonger la collecte jusqu'à la marée suivante"],"correct":"B","explanation":"Le passage indique : « Le ramassage des déchets sur une plage se déroule après la marée haute. Les organisateurs vérifient les horaires pour ne pas exposer les participants à la montée des eaux. » Cela justifie la réponse : Réduire un risque pour les participants."},{"number":20,"points":21,"passage":"Un supermarché baisse le prix de produits proches de leur date limite. L'association partenaire rappelle que ces promotions ne doivent pas inciter à acheter plus que ce que l'on consommera réellement. Les clients recevront des indications de conservation et pourront acheter une petite quantité seulement. Le magasin souhaite écouler les produits encore utilisables, pas transformer l'urgence de la vente en prétexte à remplir inutilement les paniers. L'association propose de comparer les achats avec les besoins prévus pour les repas. Une réduction importante ne constitue une économie que si les aliments sont consommés dans les conditions nécessaires.","question":"Quelle limite accompagne la promotion ?","options":["Réserver les réductions aux achats en grande quantité","Promouvoir les produits dont la date est éloignée","Éviter que le gaspillage se déplace chez les acheteurs","Limiter l'achat aux seuls produits non périssables"],"correct":"C","explanation":"Le passage indique : « Un supermarché baisse le prix de produits proches de leur date limite. L'association partenaire rappelle que ces promotions ne doivent pas inciter à acheter plus que ce que l'on consommera réellement. » Cela justifie la réponse : Éviter de déplacer le gaspillage vers les foyers."},{"number":21,"points":21,"passage":"Une forêt accueille des promeneurs sur des chemins stabilisés. Les gestionnaires ferment certains sentiers après de fortes pluies : le sol humide s'abîme davantage sous les passages répétés. Les gardes ont observé des traces profondes dans certains passages très fréquentés. Ils préfèrent fermer quelques secteurs pendant une courte période plutôt que réparer plus tard un sentier fortement dégradé. Les promeneurs sont invités à suivre ces indications même lorsque la pluie a cessé et que la surface commence à sembler sèche.","question":"Quel motif explique les fermetures ?","options":["Protéger les sols affaiblis par les pluies récentes","Faciliter le passage des véhicules d'entretien","Éviter les rencontres entre groupes de promeneurs","Préparer la réfection de tous les chemins stabilisés"],"correct":"A","explanation":"Le passage indique : « Une forêt accueille des promeneurs sur des chemins stabilisés. Les gestionnaires ferment certains sentiers après de fortes pluies : le sol humide s'abîme davantage sous les passages répétés. » Cela justifie la réponse : La fragilité temporaire du sol."},{"number":22,"points":21,"passage":"Une ville plante des arbres sur une place très minérale. Les habitants demandent aussi des points d'eau et des bancs. L'ombre sera utile, mais prendra plusieurs années à se développer. Les associations du quartier proposent des points de repos temporaires et une information sur les lieux frais déjà accessibles. Le service des espaces verts a présenté le rythme probable de croissance des plantations. La mairie souhaite éviter une promesse de confort immédiat que les arbres ne peuvent pas tenir.","question":"Pourquoi ajouter d'autres équipements ?","options":["Protéger les plantations pendant les premiers travaux","Limiter l'accès à la place avant la fin du chantier","Répondre aux besoins de fraîcheur avant que les arbres grandissent","Conserver la place libre pour de futures plantations"],"correct":"C","explanation":"Le passage indique : « Une ville plante des arbres sur une place très minérale. Les habitants demandent aussi des points d'eau et des bancs. L'ombre sera utile, mais prendra plusieurs années à se développer. » Cela justifie la réponse : Répondre aux besoins avant la croissance des arbres."},{"number":23,"points":21,"passage":"Une cantine réduit les portions servies d'avance et autorise les élèves à se resservir. Les déchets alimentaires diminuent sans limiter la quantité disponible pour ceux qui ont faim. Le personnel observe les retours de plateaux et demande aux enfants ce qui leur permet de se servir plus justement. Certains avaient l'habitude de prendre une grosse portion par crainte de manquer ensuite. Les équipes expliquent donc clairement que le complément reste possible.","question":"Quelle organisation est adoptée ?","options":["Distribuer une grande portion identique à chaque élève","Retirer le droit de se resservir pendant le repas","Servir moins d'abord, tout en permettant un complément","Réserver les portions supplémentaires au personnel"],"correct":"C","explanation":"Le passage indique : « Une cantine réduit les portions servies d'avance et autorise les élèves à se resservir. Les déchets alimentaires diminuent sans limiter la quantité disponible pour ceux qui ont faim. » Cela justifie la réponse : Adapter le premier service avec possibilité de complément."},{"number":24,"points":21,"passage":"Des pêcheurs participent à un suivi des poissons de rivière. Ils notent également les journées sans capture, car une absence d'observation apporte elle aussi une information utile. Les fiches précisent le lieu, la durée et les conditions de chaque sortie. Une journée sans poisson peut s'expliquer de plusieurs façons, qui seront discutées avec les spécialistes. Le groupe souhaite construire une série cohérente plutôt qu'une collection de belles photographies de captures.","question":"Pourquoi noter les sorties sans prise ?","options":["Pour calculer les prises seulement les jours fructueux","Pour comparer les durées de sortie de chaque bénévole","Pour inclure aussi les sorties sans résultat positif","Pour éviter de préciser les conditions de pêche"],"correct":"C","explanation":"Le passage indique : « Des pêcheurs participent à un suivi des poissons de rivière. Ils notent également les journées sans capture, car une absence d'observation apporte elle aussi une information utile. » Cela justifie la réponse : Pour éviter un relevé limité aux résultats positifs."},{"number":25,"points":21,"passage":"Une zone commerciale promet des bâtiments moins énergivores. Une enquête relève toutefois l'allongement des trajets automobiles provoqué par son implantation éloignée. Les économies du bâtiment ne suffisent pas à décrire l'effet global du projet. Les responsables du projet reconnaissent l'intérêt des bâtiments performants, mais demandent une comparaison avec d'autres emplacements possibles. Les distances et les moyens de transport disponibles seront intégrés au dossier. Ils souhaitent éviter qu'un progrès mesuré dans les murs masque une dépense supplémentaire provoquée ailleurs.","question":"Quel élément faut-il aussi considérer ?","options":["Les économies d'énergie annoncées pour les bâtiments","Les trajets automobiles liés à l'emplacement","Les dépenses d'entretien des locaux","Le prix des équipements de chauffage"],"correct":"B","explanation":"Le passage indique : « Une zone commerciale promet des bâtiments moins énergivores. Une enquête relève toutefois l'allongement des trajets automobiles provoqué par son implantation éloignée. Les économies du bâtiment ne suffisent pas à décrire l'effet global du projet. » Cela justifie la réponse : Les déplacements liés à l'emplacement."},{"number":26,"points":21,"passage":"Un agriculteur réserve une bande fleurie près de ses cultures. Elle occupe de la place, mais attire des insectes utiles. Il observe les résultats sur plusieurs saisons plutôt que promettre un bénéfice immédiat chaque année. Il a réservé un secteur témoin pour mieux comparer les évolutions avec les autres parcelles. Les variétés de fleurs ont été choisies selon leur calendrier et les conditions du sol. Certaines poussent moins bien la première année.","question":"Quelle attitude adopte-t-il ?","options":["Observer les résultats sur plusieurs saisons","Évaluer seulement la première récolte après semis","Retirer la bande fleurie après une saison peu favorable","Comparer uniquement les parcelles les plus fleuries"],"correct":"A","explanation":"Le passage indique : « Un agriculteur réserve une bande fleurie près de ses cultures. Elle occupe de la place, mais attire des insectes utiles. Il observe les résultats sur plusieurs saisons plutôt que promettre un bénéfice immédiat chaque année. » Cela justifie la réponse : Évaluer les effets dans la durée."},{"number":27,"points":21,"passage":"Une bibliothèque d'objets prête des outils rarement utilisés. Son bilan inclut désormais leur entretien : un objet partagé longtemps peut être utile, mais un matériel rapidement cassé ne remplace pas durablement plusieurs achats. Les bénévoles contrôlent désormais les pièces sensibles et expliquent les gestes qui prolongent la durée d'utilisation. Ils enregistrent aussi les réparations pour savoir quels modèles résistent à des prêts fréquents.","question":"Quel facteur devient important dans le bilan ?","options":["Le nombre de prêts comptabilisés sans examen du matériel","La quantité d'objets stockés dans les locaux","Le coût initial des cartes d'adhésion","L'entretien et la durée d'utilisation effective des objets"],"correct":"D","explanation":"Le passage indique : « Une bibliothèque d'objets prête des outils rarement utilisés. Son bilan inclut désormais leur entretien : un objet partagé longtemps peut être utile, mais un matériel rapidement cassé ne remplace pas durablement plusieurs achats. » Cela justifie la réponse : La durée réelle d'utilisation du matériel."},{"number":28,"points":21,"passage":"Un collectif installe un récupérateur d'eau pour le jardin partagé. Les réserves sont affectées en priorité aux jeunes plantations pendant les restrictions. La collecte ne signifie pas que l'eau devient illimitée. Les jardiniers suivront les volumes recueillis et les besoins de chaque secteur. Une pluie importante peut remplir le réservoir, mais une période longue sans précipitations le vide rapidement. Le collectif a choisi de prévoir ces variations dans ses règles.","question":"Quel principe de gestion est retenu ?","options":["Répartir le stock également entre tous les jardiniers","Réserver une part fixe à chaque parcelle","Utiliser l'eau à mesure que les réserves se remplissent","Affecter d'abord l'eau aux plantations prioritaires"],"correct":"D","explanation":"Le passage indique : « Un collectif installe un récupérateur d'eau pour le jardin partagé. Les réserves sont affectées en priorité aux jeunes plantations pendant les restrictions. La collecte ne signifie pas que l'eau devient illimitée. » Cela justifie la réponse : Réserver l'eau aux besoins prioritaires."},{"number":29,"points":21,"passage":"Une association propose une promenade nocturne pour observer les chauves-souris. Les participants éteignent les lampes orientées vers les refuges. Mieux voir n'autorise pas à perturber ce qu'ils viennent découvrir. Le guide présentera quelques repères sonores avant de commencer, puis choisira des points d'arrêt suffisamment éloignés des refuges. Les visiteurs pourront poser leurs questions après chaque observation pour limiter les mouvements.","question":"Quelle limite encadre l'observation ?","options":["Observer les animaux à l'entrée de leurs refuges","Respecter les refuges même si l'observation est limitée","Utiliser une faible lumière dirigée sur les zones de repos","S'approcher des animaux pour mieux les photographier"],"correct":"B","explanation":"Le passage indique : « Une association propose une promenade nocturne pour observer les chauves-souris. Les participants éteignent les lampes orientées vers les refuges. Mieux voir n'autorise pas à perturber ce qu'ils viennent découvrir. » Cela justifie la réponse : Respecter les animaux même si cela réduit la visibilité."},{"number":30,"points":26,"passage":"Le recyclage est souvent présenté comme la dernière étape évidente d'un produit. Pourtant, certains mélanges de matières sont difficiles à séparer. Un designer travaille donc sur la conception initiale : réduire cette difficulté avant la vente peut rendre le traitement final plus efficace. Des matériaux faciles à identifier et des assemblages démontables peuvent simplifier le travail des centres de traitement. Le projet associe donc les fabricants aux personnes chargées de récupérer et de séparer les produits en fin d'usage.","question":"À quel moment souhaite-t-il agir ?","options":["Lors du tri des appareils après leur utilisation","Pendant le démontage en centre de traitement","Au moment de la collecte en fin de vie","Dès la phase de conception des produits"],"correct":"D","explanation":"Le passage indique : « Le recyclage est souvent présenté comme la dernière étape évidente d'un produit. Pourtant, certains mélanges de matières sont difficiles à séparer. Un designer travaille donc sur la conception initiale : réduire cette difficulté avant la vente peut rendre le traitement final plus efficace. » Cela justifie la réponse : Lors de la conception du produit."},{"number":31,"points":26,"passage":"Une entreprise remplace ses emballages par une version plus légère. Elle doit vérifier que les produits restent protégés. Si davantage d'articles arrivent cassés, les économies d'emballage peuvent être dépassées par le coût matériel des remplacements. L'équipe réalisera des essais de transport avant de généraliser le changement. Elle regardera les emballages économisés et les articles remplacés, afin de comparer les effets sur tout le parcours plutôt que sur un seul indicateur.","question":"Quelle relation le texte met-il en avant ?","options":["Les gains d'emballage doivent être comparés aux pertes par casse","Des emballages plus légers protègent nécessairement mieux","Le bilan dépend uniquement du nombre de cartons économisés","Une protection insuffisante n'a pas d'incidence sur les déchets"],"correct":"A","explanation":"Le passage indique : « Une entreprise remplace ses emballages par une version plus légère. Elle doit vérifier que les produits restent protégés. Si davantage d'articles arrivent cassés, les économies d'emballage peuvent être dépassées par le coût matériel des remplacements. » Cela justifie la réponse : L'emballage et les pertes de produits doivent être évalués ensemble."},{"number":32,"points":26,"passage":"Les arbres d'une avenue ont été choisis pour leur résistance à la chaleur. Un spécialiste demande aussi de varier les espèces. Une plantation homogène peut être vulnérable à une maladie qui touche précisément l'espèce retenue, même si chaque arbre supporte bien le climat. La ville choisira plusieurs variétés adaptées à ses contraintes et suivra leur état au fil des saisons. Le spécialiste veut éviter de remplacer une fragilité climatique par une autre dépendance, cette fois liée à une espèce dominante.","question":"Quel intérêt présente la diversité ?","options":["Rendre plus rapide la croissance de chaque arbre","Réduire les besoins de suivi après plantation","Éviter qu'un même problème affecte tous les arbres","Remplacer l'adaptation à la chaleur par une seule espèce"],"correct":"C","explanation":"Le passage indique : « Les arbres d'une avenue ont été choisis pour leur résistance à la chaleur. Un spécialiste demande aussi de varier les espèces. Une plantation homogène peut être vulnérable à une maladie qui touche précisément l'espèce retenue, même si chaque arbre supporte bien le climat. » Cela justifie la réponse : Réduire une vulnérabilité collective."},{"number":33,"points":26,"passage":"Une campagne demande aux ménages de réduire leurs déchets. Elle obtient davantage de résultats lorsqu'elle s'accompagne de solutions pratiques : réparateurs accessibles, commerces acceptant les contenants et collecte adaptée. L'information seule laisse parfois les personnes convaincues sans possibilité d'agir facilement. Ils veulent rendre les options possibles et compréhensibles, au lieu de demander aux habitants une pratique que leur environnement quotidien ne leur permet pas facilement d'adopter.","question":"Quelle condition favorise l'action ?","options":["Multiplier les messages demandant un changement de comportement","Réduire les explications pour accélérer la sensibilisation","Fixer des objectifs sans modifier les services disponibles","Rendre les moyens de réduction simples et accessibles"],"correct":"D","explanation":"Le passage indique : « Une campagne demande aux ménages de réduire leurs déchets. Elle obtient davantage de résultats lorsqu'elle s'accompagne de solutions pratiques : réparateurs accessibles, commerces acceptant les contenants et collecte adaptée. L'information seule laisse parfois les personnes convaincues sans possibilité d'agir facilement. » Cela justifie la réponse : La présence de moyens concrets accessibles."},{"number":34,"points":26,"passage":"Un chantier réemploie des portes récupérées. Certaines nécessitent plus de travail qu'un produit neuf. L'intérêt du réemploi ne se mesure donc pas seulement à la rapidité de pose : il dépend aussi des matériaux évités, des compétences mobilisées et de la durée de vie obtenue. Ils souhaitent comprendre quels objets sont réellement remis en service et dans quelles conditions, plutôt que compter tous les éléments récupérés comme des économies déjà assurées.","question":"Quelle approche du réemploi est proposée ?","options":["Compter tous les éléments récupérés comme des économies","Comparer uniquement le prix d'achat des portes","Privilégier seulement les éléments rapides à installer","Évaluer le réemploi au-delà du seul temps de chantier"],"correct":"D","explanation":"Le passage indique : « Un chantier réemploie des portes récupérées. Certaines nécessitent plus de travail qu'un produit neuf. L'intérêt du réemploi ne se mesure donc pas seulement à la rapidité de pose : il dépend aussi des matériaux évités, des compétences mobilisées et de la durée de vie obtenue. » Cela justifie la réponse : Une appréciation dépassant la seule vitesse du chantier."},{"number":35,"points":26,"passage":"Une réserve naturelle augmente sa surface protégée. Cependant, une route coupe la liaison entre deux secteurs. Pour certains animaux, la continuité des habitats compte autant que leur superficie. Ajouter des hectares séparés peut donc améliorer un indicateur sans résoudre la principale difficulté écologique. Leur travail porte ainsi sur l'organisation de l'espace, car certains besoins ne peuvent pas être satisfaits par une simple augmentation des surfaces figurant sur la carte.","question":"Quel enjeu complète celui de la superficie ?","options":["L'augmentation du nombre d'hectares déclarés","Le maintien de passages entre les habitats","La superficie de chaque parcelle prise isolément","La distance entre les bâtiments de surveillance"],"correct":"B","explanation":"Le passage indique : « Une réserve naturelle augmente sa surface protégée. Cependant, une route coupe la liaison entre deux secteurs. Pour certains animaux, la continuité des habitats compte autant que leur superficie. Ajouter des hectares séparés peut donc améliorer un indicateur sans résoudre la principale difficulté écologique. » Cela justifie la réponse : La connexion entre les habitats."},{"number":36,"points":33,"passage":"Une municipalité propose des sacs recyclables pour ses événements. Une équipe constate que beaucoup sont jetés avec des restes alimentaires, rendant leur traitement difficile. Le choix du matériau n'était qu'une partie du problème. Sans organisation de la collecte et consignes compréhensibles, une possibilité technique de recyclage ne devient pas nécessairement un recyclage effectif. Le service d'entretien doit savoir où déposer les sacs et comment distinguer les déchets acceptés. Les participants reçoivent aussi des consignes au moment où ils utilisent le matériel, plutôt qu'une longue notice uniquement visible avant l'événement. Les organisateurs mesureront donc les quantités effectivement orientées vers le bon traitement. Ils souhaitent comparer plusieurs options, y compris la réduction du nombre de sacs distribués. Le choix d'un matériau reste important, mais le bilan doit tenir compte des gestes et des équipements qui rendent sa récupération possible dans les conditions réelles du festival.","question":"Quelle distinction est essentielle ?","options":["Des consignes initiales suffisent à assurer la collecte","Un matériau recyclable n'est pas forcément recyclé","La composition des sacs remplace toute organisation du tri","Les quantités distribuées mesurent les déchets valorisés"],"correct":"B","explanation":"Le passage indique : « Sans organisation de la collecte et consignes compréhensibles, une possibilité technique de recyclage ne devient pas nécessairement un recyclage effectif. » Cela justifie la réponse : Celle entre un matériau recyclable et son traitement réel."},{"number":37,"points":33,"passage":"Pour améliorer un cours d'eau, une association supprime certains obstacles et restaure des berges. Les résultats évoluent lentement et varient selon les saisons. Des financeurs souhaiteraient un chiffre simple chaque mois. L'équipe défend un suivi de plusieurs indicateurs sur plusieurs années. L'absence d'une hausse immédiate et régulière ne suffit pas à conclure à l'échec d'une restauration écologique. Certains effets se manifestent par le retour progressif d'espèces, d'autres par une meilleure circulation de l'eau ou par l'évolution de la végétation. Une crue peut modifier temporairement un relevé sans annuler les progrès réalisés. L'association souhaite expliquer ces variations aux habitants et aux partenaires financiers. Elle ne demande pas d'échapper à toute évaluation : elle veut un suivi capable de distinguer une difficulté durable d'une fluctuation normale.","question":"Pourquoi l'équipe refuse-t-elle un bilan mensuel unique ?","options":["Les relevés mensuels suffisent à rendre compte de chaque évolution","Les effets écologiques se manifestent à des rythmes différents","Les financeurs souhaitent déjà un suivi sur plusieurs années","Une seule espèce observée reflète l'état global de la rivière"],"correct":"B","explanation":"Le passage indique : « L'absence d'une hausse immédiate et régulière ne suffit pas à conclure à l'échec d'une restauration écologique. » Cela justifie la réponse : Les effets du projet sont progressifs et variables."},{"number":38,"points":33,"passage":"Une marque met en avant une forte baisse de consommation pour chaque appareil vendu. Dans le même temps, elle encourage les clients à multiplier les équipements connectés dans leur logement. Le bilan individuel s'améliore, mais le nombre d'appareils augmente. Une meilleure efficacité par unité ne garantit pas une réduction de la consommation totale. Les équipes commerciales mettent surtout en avant la performance du dernier modèle, sans toujours évoquer les achats supplémentaires qu'elles encouragent. Une association de consommateurs propose de présenter des exemples d'équipement complet d'un logement. Les ménages pourraient alors comparer plusieurs choix à usage semblable. La marque reconnaît qu'une amélioration technique peut être réelle tout en donnant un résultat différent à l'échelle de l'ensemble des ventes. Le débat porte donc à la fois sur les caractéristiques des appareils et sur les pratiques de renouvellement qu'un modèle commercial cherche à installer.","question":"Quelle conclusion peut-on tirer ?","options":["Une économie par appareil garantit la baisse du total","La consommation du foyer ne dépend que du modèle choisi","Le nombre d'appareils compte aussi dans le bilan énergétique","La comparaison de modèles remplace l'étude des usages"],"correct":"C","explanation":"Le passage indique : « Une meilleure efficacité par unité ne garantit pas une réduction de la consommation totale. » Cela justifie la réponse : Il faut regarder aussi le volume des équipements utilisés."},{"number":39,"points":33,"passage":"La plantation d'arbres est parfois proposée comme compensation immédiate d'émissions présentes. Les arbres peuvent contribuer au stockage du carbone, mais leur croissance prend du temps et leur survie dépend des conditions locales. Annoncer une équivalence instantanée efface ces incertitudes et risque de faire passer une promesse future pour un résultat déjà acquis. Une sécheresse, une maladie ou un changement d'usage du terrain peut réduire le stockage attendu. Les responsables d'un programme sérieux doivent donc préciser le suivi, la durée et les hypothèses sur lesquelles reposent leurs estimations. Des plantations peuvent apporter d'autres bénéfices utiles, notamment pour le paysage et la biodiversité. Ces intérêts ne doivent toutefois pas servir à faire disparaître les différences entre une réduction déjà obtenue et un engagement à long terme. Les citoyens ont besoin de ces informations pour comprendre la portée réelle des annonces et comparer des actions différentes.","question":"Quelle critique est formulée ?","options":["Une promesse de stockage futur ne prouve pas une compensation immédiate","La survie des arbres est connue au moment de planter","Les bénéfices paysagers dispensent du suivi du carbone","Une estimation initiale suffit pour vérifier le stockage"],"correct":"A","explanation":"Le passage indique : « Annoncer une équivalence instantanée efface ces incertitudes et risque de faire passer une promesse future pour un résultat déjà acquis. » Cela justifie la réponse : Une promesse de stockage futur ne vaut pas un résultat immédiat garanti."}]}$paper$::jsonb);
update academy_tcf_reading.published_papers
 set version='tcf-reading-2026-11-editorial-v4'
 where test_id='tcf-reading-01' and version='tcf-reading-2026-11-pdf-v1';
update academy_tcf_reading.published_papers
 set version='tcf-reading-2026-11-editorial-v4'
 where test_id='tcf-reading-05' and version='tcf-reading-2026-11-reference-v3';
do $verify$ begin
 if (select count(*) from academy_tcf_reading.published_papers) <> 20 then
   raise exception 'Exactly 20 published reading tests required';
 end if;
 if (select count(*) from academy_tcf_reading.published_papers
     where test_id in ('tcf-reading-01','tcf-reading-05') and version='tcf-reading-2026-11-editorial-v4')<>2 then
   raise exception 'Expected both editorial revisions published';
 end if;
 if exists(select 1 from academy_tcf_reading.published_papers
   where test_id not in ('tcf-reading-01','tcf-reading-05') and version<>'tcf-reading-2026-11-reference-v3') then
    raise exception 'Unrelated reading test version changed';
 end if;
 if exists(select 1 from academy_tcf_reading.papers
   where (id,version) in (('tcf-reading-01','tcf-reading-2026-11-editorial-v4'),('tcf-reading-05','tcf-reading-2026-11-editorial-v4'))
   and (jsonb_array_length(content->'questions')<>39 or (content->>'seconds')::integer<>3600
   or (select sum((q->>'points')::integer) from jsonb_array_elements(content->'questions') q)<>699)) then
    raise exception 'Editorial question count or point scheme mismatch';
 end if;
end $verify$;
commit;
